const brand = $('OSN Static Fields Mapping').item.json.brandCode;
const region = $('OSN Static Fields Mapping').item.json.region || "UFM";
const playerId=$input.first().json.PLAYER_ID;
const audienceCode=$input.first().json.AUDIENCE_CODE;
const csvContent = `AUDIENCE_CODE,PLAYER_ID\n${audienceCode},${playerId}`;

return {
  helpers: {
    binary: {
      createFromText: true
    }
  },
  json: {
    fileName: `${brand}-${region}.csv`
  },
  binary: {
    audience_csv: {
      data: btoa(csvContent),
      mimeType: 'text/csv',
      fileName: `${brand}-${region}.csv`
    }
  }
};

